namespace Fanex.Age.UI.Components
{
    public class WinlossReportFilter_Control : TplCore.Element.IComponent
    {
        #region Member Variables

        private string[,] _itemCollection = null;
        private bool _isShowed = true;
        private WinlossReportFilter_Template _template = new WinlossReportFilter_Template();

        #endregion

        

        #region Constructors

        public WinlossReportFilter_Control(string[,] itemCollection, bool isShowed)
        {
            this._isShowed = isShowed;
            this._itemCollection = itemCollection;
        }

        #endregion



        #region Process methods

        /// <summary>
        /// Render filter control
        /// </summary>
        private void Render()
        {
            _template.Filter.Clear();

            if (_isShowed && (_itemCollection != null) && (_itemCollection.Length > 0))
            {
                WinlossReportFilter_Filter_Block itemContent = null;
                for (int col = 0; col < _itemCollection.GetLength(1); col++)
                {
                    itemContent = new WinlossReportFilter_Filter_Block();
                    CreateItem(itemContent,
                                _itemCollection[0, col], // name index
                                _itemCollection[1, col], // text index
                                _itemCollection[2, col], // checked index
                                _itemCollection[3, col]);// js function index
                    _template.Filter.Append(itemContent);
                }
            }
        }

        /// <summary>
        /// Create option item
        /// </summary>
        /// <param name="content"></param>
        /// <param name="name"></param>
        /// <param name="text"></param>
        /// <param name="check"></param>
        /// <param name="onClick"></param>
        private void CreateItem(WinlossReportFilter_Filter_Block content, string name, string text, string check, string onClick)
        {
            //check (0..2) - 0:not show; 1:uncheck; 2:check
            if (check != "0")
            {
                content.optionId = name;
                content.text = text;
                content.isChecked = (check == "1" ? string.Empty : "checked");
                content.onClick = onClick;
            }
            else
            {
                content.Clear();
            }
        }

        #endregion



        #region IComponent Members

        void TplCore.Element.IComponent.HideLinkedResources()
        {
            throw new NotImplementedException();
        }

        public override string ToString()
        {
            Render();
            return _template.ToString();
        }

        #endregion
    }
}
